import sys

def find_centroids(n, parent, queries):
    from collections import defaultdict

    children = defaultdict(list)
    for child in range(2, n + 1):
        children[parent[child]].append(child)

    subtree_size = [1] * (n + 1)

    def dfs(node):
        for child in children[node]:
            subtree_size[node] += dfs(child)
        return subtree_size[node]

    dfs(1)

    def find_centroid(node, limit):
        for child in children[node]:
            if subtree_size[child] > limit // 2:
                return find_centroid(child, subtree_size[child])
        return node

    results = []
    for query in queries:
        centroid = find_centroid(query, subtree_size[query])
        results.append(centroid)

    return results

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    n = int(input[index])
    q = int(input[index + 1])
    index += 2
    parent = [0] * (n + 1)
    for i in range(2, n + 1):
        parent[i] = int(input[index])
        index += 1
    queries = []
    for _ in range(q):
        queries.append(int(input[index]))
        index += 1
    results = find_centroids(n, parent, queries)
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
